// Generated by site/build.mjs. Precaches the landing page and the full game for offline play.
const VERSION = 'sz-__VERSION__';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(VERSION);
    // add in small batches so one slow file doesn't abort the whole install
    for (let i = 0; i < PRECACHE.length; i += 8) await c.addAll(PRECACHE.slice(i, i + 8).map((u) => new Request(u, { cache: 'reload' })));
    self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== VERSION) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin) return; // Supabase, CDNs: network only
  if (url.pathname.startsWith('/media/') && !url.pathname.endsWith('.json')) return; // videos stream from network
  // pages, devlog, env: network first so updates show, cache fallback offline
  const fresh = req.mode === 'navigate' || /\/(devlog\.json|env\.js|media\.json)$/.test(url.pathname);
  e.respondWith((async () => {
    const c = await caches.open(VERSION);
    if (fresh) {
      try { const r = await fetch(req); if (r.ok) c.put(req, r.clone()); return r; }
      catch { return (await c.match(req, { ignoreSearch: true })) || (await c.match(url.pathname.startsWith('/play') ? '/play/' : '/')); }
    }
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const r = await fetch(req);
    if (r.ok) c.put(req, r.clone());
    return r;
  })());
});
